.desc { font-family: "EB Garamond", Georgia, serif; font-size:.95rem; line-height:1.65; color:rgba(246,244,239,.7);
  max-width:44em; margin-bottom:2.6em; }
.player { aspect-ratio:16/9; margin-bottom:2.6em; background:#16161c; }
.player iframe { width:100%; height:100%; border:0; }
.posterhero { margin-bottom:2.6em; }
.posterhero img { max-width:min(420px,100%); display:block; }
.note { font-size:.72rem; letter-spacing:.18em; text-transform:uppercase;
  color:rgba(246,244,239,.45); margin-bottom:2.6em; }
.laurels { display:flex; flex-wrap:wrap; gap:clamp(16px,3vw,36px);
  align-items:center; border-top:1px solid rgba(246,244,239,.12);
  padding-top:2.2em; }
.laurels img { height:74px; width:auto; opacity:.88;
  /* laurels come in black / white / colour – force every one to a uniform
     white silhouette so they read consistently on the dark page */
  filter: brightness(0) invert(1); }
.back { display:inline-block; margin-top:3em; color:rgba(246,244,239,.6);
  text-decoration:none; font-size:.7rem; letter-spacing:.18em;
  text-transform:uppercase; }
.back:hover { color:var(--paper); }
.artfoot { position: relative; width: 100%; height: clamp(120px, 20vh, 240px);
  background-size: cover; background-position: center; display: block; }

/* mobile legibility */
@media (max-width: 700px) {
  /* tracked uppercase labels fall to 10-11px on a phone; give them a floor */
  .series,
  .filmmeta,
  .note,
  .back { font-size: 0.78rem; }
  /* standalone links need a finger-sized target, not a 14px one */
  .back { padding-top: 11px; padding-bottom: 11px; }
  .top .name, .wordmark, footer.foot a { display: inline-block; padding-top: 11px; padding-bottom: 11px; }
}
